sourceCode['select.tsx'] = ''
  + 'import classNames from "classnames";\n'
  + 'import { useCallback, useEffect, useLayoutEffect, useState } from "react";\n'
  + '\n'
  + 'import { useJss, useTheme } from "@/components/CopyUiProvider";\n'
  + 'import { Popover, type PopoverTriggerRender } from "@/components/Popover";\n'
  + 'import { resolveStyle2 } from "@/utils/resolve-style2";\n'
  + '\n'
  + 'import { SelectList } from "./select-list";\n'
  + 'import { SelectTrigger } from "./select-trigger";\n'
  + '\n'
  + 'interface SelectProps<V extends string> {\n'
  + '  id?: string;\n'
  + '  value?: V | null;\n'
  + '  defaultValue?: V | null;\n'
  + '\n'
  + '  width?: "xs" | "sm" | "md" | "lg" | "xl" | "full";\n'
  + '\n'
  + '  options: Array<{ value: V; label: string }>;\n'
  + '  placeholder?: string;\n'
  + '  disabled?: boolean;\n'
  + '\n'
  + '  onChange?: (value: V) => void;\n'
  + '}\n'
  + '\n'
  + 'const Select = <V extends string>(props: SelectProps<V>) => {\n'
  + '  const {\n'
  + '    id,\n'
  + '    value = null,\n'
  + '    defaultValue = null,\n'
  + '    width = "md",\n'
  + '    options,\n'
  + '    placeholder = "Select an option",\n'
  + '    disabled = false,\n'
  + '    onChange,\n'
  + '  } = props;\n'
  + '\n'
  + '  const jss = useJss();\n'
  + '  const theme = useTheme();\n'
  + '\n'
  + '  const [triggerEl, setTriggerEl] = useState<HTMLButtonElement | null>(null);\n'
  + '\n'
  + '  const [internalValue, setInternalValue] = useState<V | null>(defaultValue);\n'
  + '  const [triggerWidth, setTriggerWidth] = useState(0);\n'
  + '\n'
  + '  // Update internal value when `value` prop changes.\n'
  + '  useEffect(() => {\n'
  + '    setInternalValue(value ?? null);\n'
  + '  }, [value]);\n'
  + '\n'
  + '  // Update trigger width on mount and resize.\n'
  + '  useLayoutEffect(() => {\n'
  + '    if (triggerEl) {\n'
  + '      setTriggerWidth(triggerEl.offsetWidth);\n'
  + '\n'
  + '      const ro = new ResizeObserver(() => {\n'
  + '        const width = triggerEl.offsetWidth;\n'
  + '        if (width) {\n'
  + '          setTriggerWidth(triggerEl.offsetWidth);\n'
  + '        }\n'
  + '      });\n'
  + '      ro.observe(triggerEl);\n'
  + '\n'
  + '      return () => {\n'
  + '        ro.disconnect();\n'
  + '      };\n'
  + '    }\n'
  + '  }, [triggerEl]);\n'
  + '\n'
  + '  const showLabel = internalValue\n'
  + '    ? (options.find((o) => o.value === internalValue)?.label ?? null)\n'
  + '    : null;\n'
  + '\n'
  + '  const baseStx = jss.hash({\n'
  + '    "--select-fontSize": theme.tokens.inputBaseMdFontSize,\n'
  + '    "--select-lineHeight": "1.375rem",\n'
  + '    "--select-borderColor": theme.tokens.inputBaseDefaultBorderColor,\n'
  + '    "--select-borderRadius": theme.tokens.inputBaseBorderRadius,\n'
  + '  });\n'
  + '\n'
  + '  const widthStx = jss.hash(calcWidthStx({ width }));\n'
  + '\n'
  + '  const popoverTriggerRender: PopoverTriggerRender = useCallback(\n'
  + '    ({ setRef, isOpen, onToggle }) => (\n'
  + '      <SelectTrigger\n'
  + '        id={id}\n'
  + '        ref={(el) => {\n'
  + '          setRef(el);\n'
  + '          setTriggerEl(el);\n'
  + '        }}\n'
  + '        placeholder={placeholder}\n'
  + '        className={classNames(baseStx, widthStx)}\n'
  + '        disabled={disabled}\n'
  + '        isOpen={isOpen}\n'
  + '        onToggle={onToggle}\n'
  + '        showLabel={showLabel}\n'
  + '      />\n'
  + '    ),\n'
  + '    [id, placeholder, baseStx, widthStx, disabled, showLabel],\n'
  + '  );\n'
  + '\n'
  + '  return (\n'
  + '    <Popover>\n'
  + '      <Popover.Trigger render={popoverTriggerRender} />\n'
  + '      <Popover.Portal\n'
  + '        onClickOutside={({ closePortal }) => closePortal()}\n'
  + '        render={({ setRef, togglePortal, isOpen, floatingStyles }) =>\n'
  + '          isOpen && (\n'
  + '            <SelectList\n'
  + '              ref={setRef}\n'
  + '              className={baseStx}\n'
  + '              style={floatingStyles}\n'
  + '              options={options}\n'
  + '              internalValue={internalValue}\n'
  + '              width={triggerWidth}\n'
  + '              onItemClicked={(v) => {\n'
  + '                togglePortal();\n'
  + '\n'
  + '                if (!disabled) {\n'
  + '                  setInternalValue(v);\n'
  + '                  onChange?.(v);\n'
  + '                }\n'
  + '              }}\n'
  + '            />\n'
  + '          )\n'
  + '        }\n'
  + '      />\n'
  + '    </Popover>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'Select.displayName = "Select";\n'
  + '\n'
  + 'const calcWidthStx = resolveStyle2({\n'
  + '  width: {\n'
  + '    xs: { "--selectTrigger-w": "8rem" },\n'
  + '    sm: { "--selectTrigger-w": "12rem" },\n'
  + '    md: { "--selectTrigger-w": "16rem" },\n'
  + '    lg: { "--selectTrigger-w": "20rem" },\n'
  + '    xl: { "--selectTrigger-w": "24rem" },\n'
  + '    full: { "--selectTrigger-w": "100%" },\n'
  + '  },\n'
  + '});\n'
  + '\n'
  + 'export { Select };\n'
  ;

